def oof_target_encode(train, y, test, n_splits=5):
    prior = y.mean()
    oof = pd.Series(index=train.index, dtype=float)
    for tr_idx, va_idx in KFold(n_splits, shuffle=True, random_state=SEED).split(train):
        m = y.iloc[tr_idx].groupby(train.iloc[tr_idx]).mean()   # fold-only means
        oof.iloc[va_idx] = train.iloc[va_idx].map(m).fillna(prior).values
    return oof, test.map(y.groupby(train).mean()).fillna(prior)
